const tokens = new Map();
let n = 0;
const issue = (family) => {
  const token = `rt-${++n}`;
  tokens.set(token, { family, used: false });
  return token;
};
function refresh(token) {
  const entry = tokens.get(token);
  if (!entry) return "unknown";
  if (entry.used) {
    for (const [t, e] of tokens) if (e.family === entry.family) tokens.delete(t);
    return "reuse: family revoked";
  }
  entry.used = true;
  return issue(entry.family);
}

const first = issue("login-1");
