function checkClaims(header, claims, { now, issuer, audience, leeway }) {
  if (header.alg !== "HS256") return "bad alg";
  if (typeof claims.exp !== "number" || now > claims.exp + leeway) return "expired";
  if (claims.iss !== issuer) return "wrong issuer";
  if (claims.aud !== audience) return "wrong audience";
  return "ok";
}

