function createSessions({ idleMs, absoluteMs }) {
  const store = new Map();
  return {
    start(token, userId, now) {
      store.set(token, { userId, createdAt: now, lastSeen: now });
    },
    read(token, now) {
      const s = store.get(token);
      if (!s) return null;
      if (now - s.lastSeen >= idleMs || now - s.createdAt >= absoluteMs) {
        store.delete(token);
        return null;
      }
      s.lastSeen = now;
      return s.userId;
    },
  };
}

