function createThrottle() {
  const accounts = new Map();
  return {
    attempt(account, ok, now) {
      const state = accounts.get(account) ?? { failures: 0, nextAt: 0 };
      accounts.set(account, state);
      if (now < state.nextAt) return `wait ${Math.ceil((state.nextAt - now) / 1000)} s`;
      if (ok) {
        state.failures = 0;
        state.nextAt = 0;
        return "ok";
      }
      state.failures++;
      if (state.failures > 5) state.nextAt = now + 2 ** (state.failures - 6) * 1000;
      return "wrong";
    },
  };
}

const throttle = createThrottle();
const results = [];
for (let i = 0; i < 6; i++) results.push(throttle.attempt("ada", false, 0));
results.push(throttle.attempt("ada", true, 500));
results.push(throttle.attempt("ada", false, 1000));
results.push(throttle.attempt("ada", true, 2500));
results.push(throttle.attempt("ada", true, 3000));
console.log(results.join(", "));

