function parsePhc(stored) {
  const parts = stored.split("$");
  if (parts.length !== 6 || parts[0] !== "") return null;
  const [, algorithm, version, costs, salt, hash] = parts;
  const params = Object.fromEntries(costs.split(",").map((pair) => pair.split("=")).map(([k, v]) => [k, Number(v)]));
  return { algorithm, version: Number(version.replace("v=", "")), params, salt, hash };
}

function needsRehash(stored, current) {
  const parsed = parsePhc(stored);
  if (!parsed || parsed.algorithm !== "argon2id") return true;
  return ["m", "t", "p"].some((k) => parsed.params[k] !== current[k]);
}

const current = { m: 19456, t: 2, p: 1 };
console.log(parsePhc("$argon2id$v=19$m=19456,t=2,p=1$c2FsdA$aGFzaA"));
console.log(needsRehash("$argon2id$v=19$m=19456,t=2,p=1$c2FsdA$aGFzaA", current));
console.log(needsRehash("$argon2id$v=19$m=65536,t=3,p=1$c2FsdA$aGFzaA", current));
