const DUMMY_HASH = "hash-of-a-random-password";
const users = new Map([["ada@example.com", { id: 7, hash: "hash-of:a long passphrase" }]]);
let checks = 0;
const check = async (password, hash) => {
  checks++;
  return hash === `hash-of:${password}`;
};

async function logIn(users, email, password, check) {
  const user = users.get(email.toLowerCase());
  const ok = await check(password, user?.hash ?? DUMMY_HASH);
  if (!user || !ok) return "Wrong e-mail or password";
  return `welcome, user ${user.id}`;
}

console.log(await logIn(users, "ada@example.com", "a long passphrase", check));
console.log(await logIn(users, "ada@example.com", "guess", check));
console.log(await logIn(users, "nobody@example.com", "guess", check));
console.log("password checks:", checks);
